class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3, bias=False, dtype=torch.bfloat16)

    def forward(self, x):
        weight = self.conv1.weight
        b, c, h, w = x.shape
        oc = weight.shape[0]
        kh, kw = weight.shape[2], weight.shape[3]
        oh, ow = h - kh + 1, w - kw + 1
        out = torch.empty((b, oc, oh, ow), dtype=x.dtype, device=x.device)
        total_spatial = oh * ow
        module = _get_ptx_module()
        block_x = 256
        tiles_x = (ow + 15) // 16
        tiles_y = (oh + 15) // 16
        grid_x = tiles_x * tiles_y
        module.launch(
            "conv3x3_bf16_kernel",
            grid=(grid_x, (oc + 1) // 2, b),
            block=(block_x, 1, 1),
            arguments=[x, weight, out, u32(total_spatial), u32(ow), u32(h), u32(w), u32(oc)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
